#include <iostream>
#include <memory>
#include <utility>

struct Request {
    int id = 7;

    ~Request() {
        std::cout << "销毁请求\n";
    }
};

int main() {
    auto req = std::make_unique<Request>();

    {
        auto next = std::move(req);
        std::cout << "处理请求 " << next->id << "\n";
    } // A

    if (!req) {
        std::cout << "req 已空\n";
    }
} // B
